def performance_summary(request_count: int, duration_seconds: float) -> str:
    """Return a single-line performance summary for a given request count and duration."""
    if request_count < 0:
        raise ValueError("request_count cannot be negative.")
    if duration_seconds <= 0:
        raise ValueError("duration_seconds must be greater than zero.")

    rps = request_count / duration_seconds
    avg_ms = (duration_seconds / request_count * 1000) if request_count > 0 else 0.0

    return (
        f"Processed {request_count:,} requests in {duration_seconds:.2f}s "
        f"({rps:,.2f} req/s, {avg_ms:.2f} ms/req)"
    )


# Example usage
if __name__ == "__main__":
    print(performance_summary(1500, 12.5))
    # Output: Processed 1,500 requests in 12.50s (120.00 req/s, 8.33 ms/req)
```

