def format_performance_summary(request_count: int, duration_seconds: float) -> str:
    """Return a single-line performance summary for a given request count and duration."""
    if request_count < 0:
        raise ValueError("request_count must be non-negative")
    if duration_seconds <= 0:
        raise ValueError("duration_seconds must be greater than zero")

    rps = request_count / duration_seconds
    avg_latency_ms = (duration_seconds / request_count) * 1000 if request_count > 0 else 0.0

    return (
        f"Requests: {request_count:,} | "
        f"Duration: {duration_seconds:.2f}s | "
        f"Throughput: {rps:,.2f} req/s | "
        f"Avg Latency: {avg_latency_ms:.2f} ms"
    )


# Example usage
if __name__ == "__main__":
    print(format_performance_summary(1500, 12.5))
    # Output: Requests: 1,500 | Duration: 12.50s | Throughput: 120.00 req/s | Avg Latency: 8.33 ms
```

